(function(){
  var root=document.querySelector('.s-game_section');
  if(!root||root.dataset.inited)return;root.dataset.inited='1';
  function $(s){return root.querySelector(s);}
  var cv=$('.js-canvas'),ctx=cv.getContext('2d');
  var W=440,H=680,GROUND=580,WORLD=2200;
  var overlay=$('.js-overlay');
  var panels=Array.prototype.slice.call(root.querySelectorAll('.js-panel'));
  var promptEl=$('.js-prompt'),heartsEl=$('.js-hearts');
  var countdownEl=$('.js-countdown'),timer=null;
  var IDS=['hero_idle','hero_run1','hero_run2','hero_run3','hero_run4','hero_jump','tile_ground','tile_platform','tile_float','flag_off','flag_on','lantern','coin_heart','door_finish','bg_hills'];
  var IMG={};
  IDS.forEach(function(id){var im=new Image();var el=root.querySelector('[data-imgid="'+id+'"]');if(el){im.src=el.currentSrc||el.src||'';}IMG[id]=im;});
  if('MutationObserver' in window){var pre=$('.js-preload');if(pre){new MutationObserver(function(muts){muts.forEach(function(m){var t=m.target;var id=t.getAttribute&&t.getAttribute('data-imgid');if(id&&IMG[id]){IMG[id].src=t.currentSrc||t.src||'';}});}).observe(pre,{attributes:true,subtree:true,attributeFilter:['src']});}}
  function draw(img,x,y,w,h){if(img&&img.complete&&img.naturalWidth>0){try{ctx.drawImage(img,x,y,w,h);return true;}catch(e){}}return false;}
  function box(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h);}
  var grounds=[{x:0,w:520},{x:580,w:520},{x:1160,w:520},{x:1740,w:460}];
  var plats=[{x:110,y:484,w:96,h:20},{x:640,y:476,w:64,h:32,float:true},{x:800,y:484,w:96,h:20},{x:1330,y:470,w:64,h:32,float:true},{x:1450,y:484,w:96,h:20},{x:1780,y:500,w:96,h:20},{x:1930,y:420,w:64,h:32,float:true}];
  var flags=[{x:150,y:484,panel:'couple',done:false},{x:664,y:476,panel:'datetime',done:false},{x:1240,y:GROUND,panel:'venue',done:false},{x:1954,y:420,panel:'gift',done:false}];
  var door={x:2080,y:GROUND,panel:'finale',done:false};
  var coins=[{x:150,y:438,taken:false},{x:664,y:430,taken:false},{x:840,y:438,taken:false},{x:1240,y:498,taken:false},{x:1362,y:424,taken:false},{x:1490,y:438,taken:false},{x:1954,y:374,taken:false},{x:2100,y:520,taken:false}];
  var lanterns=[{x:40,y:496},{x:760,y:396},{x:1290,y:496},{x:1700,y:300},{x:2000,y:496}];
  var hearts=0,cam=0,T=0;
  var P={x:24,y:GROUND-42,w:26,h:42,vy:0,face:1,ground:false,anim:0};
  var safe={x:24,y:GROUND-42};
  var input={l:0,r:0},jumpQueued=false;
  function isField(t){return t&&(t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.tagName==='SELECT');}
  document.addEventListener('keydown',function(e){
    if(isField(e.target))return;
    if(overlay&&!overlay.hidden)return;
    var k=e.key;
    if(k==='ArrowLeft'||k==='a'||k==='A'){input.l=1;e.preventDefault();}
    else if(k==='ArrowRight'||k==='d'||k==='D'){input.r=1;e.preventDefault();}
    else if(k==='ArrowUp'||k==='w'||k==='W'||k===' '){jumpQueued=true;e.preventDefault();}
    else if(k==='e'||k==='E'||k==='Enter'){doInteract();}
  });
  document.addEventListener('keyup',function(e){var k=e.key;if(k==='ArrowLeft'||k==='a'||k==='A')input.l=0;else if(k==='ArrowRight'||k==='d'||k==='D')input.r=0;});
  root.querySelectorAll('.js-btn').forEach(function(b){
    var k=b.getAttribute('data-k');
    function on(e){e.preventDefault();if(k==='jump'){jumpQueued=true;}else if(k==='act'){doInteract();}else{input[k]=1;}}
    function off(e){if(e)e.preventDefault();if(k!=='jump'&&k!=='act')input[k]=0;}
    b.addEventListener('touchstart',on,{passive:false});
    b.addEventListener('touchend',off);
    b.addEventListener('touchcancel',off);
    b.addEventListener('mousedown',on);
    b.addEventListener('mouseup',off);
    b.addEventListener('mouseleave',function(){if(k!=='jump'&&k!=='act')input[k]=0;});
  });
  cv.addEventListener('pointerdown',function(){try{cv.focus();}catch(e){}});
  function near(){var cx=P.x+P.w/2,best=null,bd=1e9;flags.concat([door]).forEach(function(f){var d=Math.abs(cx-f.x);if(d<48&&d<bd){bd=d;best=f;}});return best;}
  function doInteract(){var f=near();if(f){f.done=true;openPanel(f.panel);}}
  function currentDateTime(){var dEl=root.querySelector('[data-field="event_date"]');var tEl=root.querySelector('[data-field="event_time"]');var d=dEl?dEl.textContent.trim():'';var t=tEl?tEl.textContent.trim():'00:00';var dt=new Date(d+'T'+(t.length===5?t+':00':t));return isNaN(dt.getTime())?null:dt;}
  function tick(){if(!countdownEl)return;var target=currentDateTime();if(!target){countdownEl.textContent='';return;}var diff=target.getTime()-Date.now();if(diff<=0){countdownEl.textContent='Hari bahagia telah tiba!';return;}var s=Math.floor(diff/1000);var dd=Math.floor(s/86400),hh=Math.floor(s%86400/3600),mm=Math.floor(s%3600/60),ss=s%60;countdownEl.textContent=dd+' hari : '+hh+' jam : '+mm+' mnt : '+ss+' dtk';}
  function openPanel(name){panels.forEach(function(p){p.hidden=p.getAttribute('data-panel')!==name;});overlay.hidden=false;if(name==='datetime'){tick();if(timer)clearInterval(timer);timer=setInterval(tick,1000);}var m=root.querySelector('.s-game_section__modal');if(m)m.scrollTop=0;}
  function closePanel(){overlay.hidden=true;if(timer){clearInterval(timer);timer=null;}}
  root.querySelectorAll('.js-close').forEach(function(b){b.addEventListener('click',closePanel);});
  overlay.addEventListener('click',function(e){if(e.target===overlay)closePanel();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&overlay&&!overlay.hidden)closePanel();});
  function solidAt(pl){return P.vy>=0&&P.x+P.w>pl.x&&P.x<pl.x+pl.w;}
  function collide(){
    P.ground=false;
    for(var i=0;i<plats.length;i++){var pl=plats[i];if(solidAt(pl)){var feet=P.y+P.h;if(feet>=pl.y&&feet<=pl.y+Math.max(14,P.vy+2)){P.y=pl.y-P.h;P.vy=0;P.ground=true;}}}
    for(var g=0;g<grounds.length;g++){var gr=grounds[g];if(P.vy>=0&&P.x+P.w>gr.x&&P.x<gr.x+gr.w){var f2=P.y+P.h;if(f2>=GROUND&&f2<=GROUND+Math.max(14,P.vy+2)){P.y=GROUND-P.h;P.vy=0;P.ground=true;}}}
    if(P.y+P.h>=H){P.y=H-P.h;P.vy=0;P.ground=true;}
    if(P.ground){safe.x=P.x;safe.y=P.y;}
  }
  function update(dt){
    var mv=0;if(input.l)mv-=1;if(input.r)mv+=1;
    P.x+=mv*2.6;if(mv!==0)P.face=mv;
    if(mv!==0&&P.ground)P.anim+=dt*8;
    if(P.x<0)P.x=0;if(P.x>WORLD-P.w)P.x=WORLD-P.w;
    P.vy+=0.55;if(P.vy>12)P.vy=12;
    if(jumpQueued){if(P.ground){P.vy=-11.5;P.ground=false;}jumpQueued=false;}
    P.y+=P.vy;collide();
    if(P.y>H+60){P.x=safe.x;P.y=safe.y-10;P.vy=0;}
    var cx=P.x+P.w/2,cy=P.y+P.h/2;
    coins.forEach(function(c){if(!c.taken&&Math.abs(cx-c.x)<26&&Math.abs(cy-c.y)<30){c.taken=true;hearts++;if(heartsEl)heartsEl.textContent='♥ '+hearts+'/8';}});
    T+=dt;var tx=P.x+P.w/2-W*0.38;
    if(tx<0)tx=0;if(tx>WORLD-W)tx=WORLD-W;
    cam+=(tx-cam)*Math.min(1,dt*6);
  }
  function heroFrame(){if(!P.ground)return IMG.hero_jump;if(input.l||input.r){var f=[IMG.hero_run1,IMG.hero_run2,IMG.hero_run3,IMG.hero_run4];return f[Math.floor(P.anim)%4];}return IMG.hero_idle;}
  function vis(x,w){return x+w>cam-60&&x<cam+W+60;}
  function render(){
    ctx.clearRect(0,0,W,H);
    box(0,0,W,H,'#1b2340');
    var bg=IMG.bg_hills;
    for(var L=0;L<2;L++){
      var bw=880,bh=330,by=150,f=L===0?0.25:0.5;
      var off=-((cam*f)%bw);
      for(var bx=off-bw;bx<W+bw;bx+=bw){if(!draw(bg,bx,by,bw,bh)){box(bx,by,bw,40,'#2a2f55');}}
    }
    box(0,190,W,H-190,'#232a4a');
    grounds.forEach(function(gr){
      if(!vis(gr.x,gr.w))return;
      for(var x=gr.x;x<gr.x+gr.w;x+=32){if(!draw(IMG.tile_ground,x-cam,GROUND,32,32))box(x-cam,GROUND,32,32,'#8a5a2b');}
      box(gr.x-cam,GROUND,gr.w,H-GROUND,'rgba(0,0,0,0.18)');
    });
    plats.forEach(function(pl){
      if(!vis(pl.x,pl.w))return;
      if(pl.float){if(!draw(IMG.tile_float,pl.x-cam,pl.y,pl.w,pl.h))box(pl.x-cam,pl.y,pl.w,pl.h,'#b07a45');}
      else{var ok=false;for(var x=pl.x;x<pl.x+pl.w;x+=32){if(draw(IMG.tile_platform,x-cam,pl.y,32,20))ok=true;}if(!ok)box(pl.x-cam,pl.y,pl.w,20,'#6fbf5f');}
    });
    lanterns.forEach(function(l,i){var lx=l.x+Math.sin(T*0.8+i*1.3)*10,ly=l.y+Math.sin(T*1.1+i*1.7)*12;if(vis(lx,24)&&!draw(IMG.lantern,lx-cam,ly,24,40))box(lx-cam+8,ly,8,24,'#f6c453');});
    if(vis(door.x-24,48)&&!draw(IMG.door_finish,door.x-24-cam,door.y-72,48,72))box(door.x-24-cam,door.y-72,48,72,'#f6c453');
    coins.forEach(function(c){if(c.taken||!vis(c.x-9,18))return;if(!draw(IMG.coin_heart,c.x-9-cam,c.y-9,18,18)){ctx.fillStyle='#ff6b6b';ctx.beginPath();ctx.arc(c.x-cam,c.y,7,0,7);ctx.fill();}});
    flags.forEach(function(f){if(!vis(f.x-16,32))return;var im=f.done?IMG.flag_on:IMG.flag_off;if(!draw(im,f.x-16-cam,f.y-56,32,56))box(f.x-2-cam,f.y-56,4,56,'#b07a45');});
    var img=heroFrame();
    var px=P.x-cam,py=P.y;
    if(P.face<0){ctx.save();ctx.translate(px+P.w/2,0);ctx.scale(-1,1);ctx.translate(-(px+P.w/2),0);}
    if(!draw(img,px,py,P.w,P.h))box(px,py,P.w,P.h,'#3e3a7a');
    if(P.face<0)ctx.restore();
    var n=near();
    if(promptEl)promptEl.hidden=!(n&&overlay.hidden);
  }
  var bgmAudio=$('.js-bgm'),bgmSrc=$('.js-bgm-src'),bgmBtn=$('.js-music'),bgmWanted=true;function bgmUrl(){return bgmSrc?bgmSrc.textContent.trim():'';}function bgmSync(){if(!bgmAudio)return;var u=bgmUrl();if(u&&bgmAudio.getAttribute('src')!==u)bgmAudio.setAttribute('src',u);}function bgmPlay(){if(!bgmAudio||!bgmUrl())return;bgmSync();try{var pr=bgmAudio.play();if(pr&&pr.catch)pr.catch(function(){});}catch(e){}}if(bgmSrc&&'MutationObserver' in window){new MutationObserver(function(){bgmSync();if(bgmWanted&&bgmAudio&&bgmAudio.paused)bgmPlay();}).observe(bgmSrc,{childList:true,characterData:true,subtree:true});}['pointerdown','touchstart'].forEach(function(ev){root.addEventListener(ev,function(){if(bgmWanted)bgmPlay();},{passive:true});});document.addEventListener('keydown',function(){if(bgmWanted)bgmPlay();});if(bgmBtn){bgmBtn.addEventListener('click',function(e){e.stopPropagation();bgmWanted=!bgmWanted;if(bgmAudio&&bgmUrl()){if(bgmWanted){bgmPlay();}else{bgmAudio.pause();}}bgmBtn.textContent=bgmWanted?'\u266a':'\u2715';bgmBtn.setAttribute('aria-pressed',bgmWanted?'true':'false');});}var last=0;
  function loop(ts){var dt=Math.min(0.05,(ts-last)/1000||0.016);last=ts;if(overlay.hidden)update(dt);render();requestAnimationFrame(loop);}
  requestAnimationFrame(loop);
})();
